const mKeys=['facilities','users','queues','bookings','subscriptions'],opts=[['All','Active','Pending','Suspended'],['All','Citizen','Employee','Facility admin'],['All','Open','Paused','Closed'],['All','Completed','Scheduled','Cancelled'],['This month','This year']];
