function cards(){return '<div class="metrics">'+mKeys.map((k,i)=>{let ch=choices[i]||opts[i][0],r=rows(k),v=i===4?money(ch==='This month'?monthly().at(-1):monthly().slice(live?11-new Date().getMonth():0).reduce((a,b)=>a+b,0)):fmt(r.filter(x=>ch==='All'?(i!==2||!['Closed','Archived'].includes(x.state)):(x.role===ch||x.state===ch)).length);return '<div class="card"><div class="line">'+tile(i===4?'wallet':k,i)+'<button aria-label="'+t('Filter','تصفية')+' '+titles()[i]+'" class="dots" onclick="menu=menu==='+i+'?-1:'+i+';render()">···</button></div>'+(menu===i?'<div class="menu">'+opts[i].map(x=>'<button onclick="choices['+i+']=\''+x+'\';menu=-1;render()">'+(ch===x?'✓ ':'')+tr(x)+'</button>').join('')+'</div>':'')+'<div class="cardlabel">'+titles()[i]+'</div><div class="line"><strong class="value">'+v+'</strong><svg class="spark" viewBox="0 0 65 30"><polyline fill="none" stroke="'+colors[i][0]+'" stroke-width="2" points="'+histories[i].map((y,j)=>j*6.4+','+(35-y)).join(' ')+'"/></svg></div><div class="meta">'+(ch!==opts[i][0]?tr(ch):[t('Across the platform','على مستوى المنصة'),t('All account types','جميع أنواع الحسابات'),t('Open and paused','مفتوحة ومتوقفة'),t('Total reservations','إجمالي الحجوزات'),t('Monthly subscriptions','الاشتراكات الشهرية')][i])+'</div></div>'}).join('')+'</div>'}
function chartPanel(){const rev=metric==='Revenue',n=parseInt(period),v=(live?liveMonths(rev):rev?monthly():Array.from({length:11},(_,i)=>data.bookings.filter(x=>+x.date?.slice(5,7)===i+1).length));let series=live?v.slice(-n):(n===12?[rev?7600:3070,...v]:v.slice(-n)),end=live?new Date().getMonth():10,top=rev?Math.max(30000,...series):Math.max(6000,...series),w=600,h=145,left=45;const points=series.map((v,i)=>[left+i*(w-left-12)/(series.length-1),12+(1-v/top)*h]);let path='M'+points[0].join(',');points.slice(1).forEach(([x,y],i)=>{let [px,py]=points[i],mid=(px+x)/2;path+=' C'+mid+','+py+' '+mid+','+y+' '+x+','+y});const months=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'],am=['ينا','فبر','مار','أبر','ماي','يون','يول','أغس','سبت','أكت','نوف','ديس'];return '<div class="panelhead"><div><h2>'+t('Platform performance','أداء المنصة')+'</h2><p>'+t('Subscription revenue and booking trends','اتجاهات إيرادات الاشتراكات والحجوزات')+'</p></div>'+chartOptions(['3 months','6 months','12 months'],period,'period=this.value;render()')+'</div><div class="charthead"><span class="legend">'+(rev?titles()[4]:L('bookings'))+'</span><div class="seg">'+['Revenue','Bookings'].map(x=>'<button class="'+(metric===x?'on':'')+'" onclick="metric=\''+x+'\';render()">'+(x==='Bookings'?L('bookings'):tr(x))+'</button>').join('')+'</div></div><svg dir="ltr" class="chart" viewBox="0 0 600 182" preserveAspectRatio="none" role="img" aria-label="'+(rev?titles()[4]:L('bookings'))+'"><defs><linearGradient id="fill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#39b89c" stop-opacity=".29"/><stop offset="1" stop-color="#39b89c" stop-opacity=".025"/></linearGradient></defs>'+[0,1,2,3,4].map(i=>'<path stroke="#dce4e8" stroke-dasharray="3 4" d="M45 '+(12+i*h/4)+'H590"/><text x="0" y="'+(16+i*h/4)+'">'+(rev?'$':'')+Math.round(top*(1-i/4)/100)/10+'k</text>').join('')+'<path fill="url(#fill)" d="'+path+' L588 157 H45Z"/><path fill="none" stroke="#079984" stroke-width="3" d="'+path+'"/>'+points.map(([x,y],i)=>'<circle cx="'+x+'" cy="'+y+'" r="4" fill="white" stroke="#079984" stroke-width="2"><title>'+fmt(series[i])+'</title></circle><text text-anchor="middle" x="'+x+'" y="177">'+(ar?am:months)[(end-series.length+1+i+12)%12]+'</text>').join('')+'</svg>'}
