function listing(){const k=page,a=rows(k);return head(L(k),t('Manage records across the DAWROK platform.','إدارة السجلات على مستوى منصة دورك.'),(live&&!liveCreates.includes(k)?'':btn(addText()[k],"edit('"+k+"')")))+'<div class="panel section"><div class="panelhead"><h2>'+L(k)+' <span class="muted">('+fmt(a.length)+')</span></h2></div><div class="toolbar"><input aria-label="'+t('Search records','البحث في السجلات')+'" placeholder="'+t('Search records…','ابحث في السجلات…')+'" value="'+esc(query)+'" oninput="query=this.value;pg=0;updateTable()">'+chartOptions(['All',...states[k]],filter,'filter=this.value;pg=0;updateTable()')+'</div><div id="records">'+table()+'</div></div>'}
const updateTable=()=>{$('records').innerHTML=table()};
function table(){const k=page,a=rows(k).filter(r=>(filter==='All'||r.state===filter)&&(!query||[r.raw?.key,r.id,display(k,r),r.name,r.arabic,detail(k,r)].join(' ').toLowerCase().includes(query.toLowerCase())));pg=Math.min(pg,Math.max(0,Math.ceil(a.length/12)-1));return '<div class="tablebox"><table><thead><tr>'+['ID',t('Name','الاسم'),t('Details','التفاصيل'),t('Status','الحالة'),t('Actions','الإجراءات')].map(s=>'<th>'+s+'</th>').join('')+'</tr></thead><tbody>'+a.slice(pg*12,pg*12+12).map(r=>'<tr><td>'+esc(live?r.raw.key:'#'+r.id)+'</td><td><b>'+esc(display(k,r))+'</b>'+(k==='users'?'<small>'+esc(tr(r.role))+'</small>':'')+'</td><td>'+esc(detail(k,r))+'</td><td><span class="badge">'+esc(tr(r.state))+'</span></td><td>'+recordActions(k,r)+'</td></tr>').join('')+'</tbody></table></div>'+(!a.length?'<p>'+t('No matching records.','لا توجد سجلات مطابقة.')+'</p>':'')+'<div class="row"><button class="outline" '+(!pg?'disabled':'')+' onclick="pg--;updateTable()">'+t('Previous','السابق')+'</button><span>'+fmt(pg+1)+' / '+fmt(Math.max(1,Math.ceil(a.length/12)))+'</span><button class="outline" '+((pg+1)*12>=a.length?'disabled':'')+' onclick="pg++;updateTable()">'+t('Next','التالي')+'</button></div>'}
function modal(title,body){let d=$('dlg');d.innerHTML='<div class="panelhead"><h2>'+title+'</h2><button aria-label="'+t('Close','إغلاق')+'" onclick="dlg.close()">✕</button></div>'+body;if(!d.open)d.showModal()}
const field=(key,label,val='',type='text')=>'<label>'+label+'<input required name="'+key+'" type="'+type+'" value="'+esc(val)+'" '+(type==='number'?'min="0" step="0.01"':'')+'></label>';
const select=(key,label,options,val)=>'<label>'+label+'<select required name="'+key+'">'+options.map(x=>{const [v,n]=Array.isArray(x)?x:[x,tr(x)];return '<option value="'+esc(v)+'" '+(String(val)===String(v)?'selected':'')+'>'+esc(n)+'</option>'}).join('')+'</select></label>';
const foot=()=>'<div class="formfoot"><button class="outline" type="button" onclick="dlg.close()">'+t('Cancel','إلغاء')+'</button><button class="primary">'+t('Save changes','حفظ التغييرات')+'</button></div>';
function edit(k,id){if(k==='categories')return openCategoryForm(id);if(live)return liveEdit(k,id);let r=get(k,id)||{},f='',fl=t('Facility','المنشأة'),plans=['Basic','Professional'],ft=()=>select('facility',fl,data.facilities.map(x=>[x.id,name(x)]),r.facility);if(!['subscriptions','bookings'].includes(k))f+=field('name',k==='notifications'?t('Title','العنوان'):t('Name','الاسم'),r.name);if(['facilities','users','staff'].includes(k))f+=field('email',t('Account email','بريد الحساب'),r.email,'email');if(k==='facilities'){f+=select('plan',t('Subscription plan','خطة الاشتراك'),plans,r.plan);if(!id)f+=field('amount',t('Monthly subscription (USD)','الاشتراك الشهري بالدولار'),150,'number')}if(k==='users')f+=select('role',t('Account type','نوع الحساب'),opts[1].slice(1),r.role||'Citizen');if(['staff','subscriptions','queues','users'].includes(k))f+=ft();if(k==='subscriptions')f+=select('plan',t('Plan','الخطة'),plans,r.plan)+field('amount',t('Monthly amount (USD)','القيمة الشهرية بالدولار'),r.amount||150,'number')+field('date',t('Start date','تاريخ البدء'),r.date||'2026-11-27','date');if(k==='bookings')f+=field('user',t('Beneficiary user ID','رقم حساب المستفيد'),r.user||417,'number')+select('queue',t('Queue','الطابور'),data.queues.map(x=>[x.id,'#'+x.id+' · '+name(x)+' · '+name(get('facilities',x.facility))]),r.queue)+field('date',t('Booking date','تاريخ الحجز'),r.date||'2026-11-27','date');if(k==='notifications')f+=select('audience',t('Audience','الجمهور'),['All users','Facilities','Staff'],r.audience)+'<label>'+t('Message','الرسالة')+'<textarea required name="body">'+esc(r.body)+'</textarea></label>';f+=select('state',t('Status','الحالة'),states[k],r.state);modal(id?t('Edit record','تعديل السجل'):addText()[k],'<form id="editform">'+f+'<p id="error" role="alert"></p>'+foot()+'</form>');$('editform').onsubmit=e=>{e.preventDefault();let o=Object.fromEntries(new FormData(e.target));if(k==='bookings'&&get('users',o.user)?.role!=='Citizen'){ $('error').textContent=t('Enter an existing citizen account ID.','أدخلي رقم حساب مواطن موجود.');return}for(let key of ['user','facility','queue','amount'])if(key in o)o[key]=+o[key];if(o.email&&rows(k==='staff'?'users':k).some(x=>x.id!==id&&x.email.toLowerCase()===o.email.toLowerCase())){$('error').textContent=t('This email is already in use.','هذا البريد مستخدم بالفعل.');return}const rid=id||next(k==='staff'?'users':k);let item={...r,...o,id:rid};if(o.name!==r.name)item.arabic='';if(k==='staff')item.role='Employee';if(k==='users'&&item.role==='Citizen')item.facility=0;if(k==='bookings')item.name=r.name||'DW-'+(10000+rid);write(k,item,rid);if(k==='facilities'&&!id){const sid=next('subscriptions'),uid=next('users');write('subscriptions',{id:sid,facility:rid,amount:o.amount,plan:o.plan,state:o.state==='Active'?'Active':'Pending',date:new Date().toISOString().slice(0,10)},sid);write('users',{id:uid,name:o.name,email:o.email,facility:rid,role:'Facility admin',state:o.state==='Active'?'Active':'Suspended'},uid)}log(k,id?'Updated':'Created',display(k,item));$('dlg').close();render()}}
function log(k,action,n){cache.log.unshift({k,action,name:n,time:Date.now()});save()}
function removeRow(k,id){if(live||k==='categories')return confirmAdminDelete(k,id);let r=get(k,id);const deps=(k==='facilities'&&(data.queues.some(x=>x.facility===id)||data.subscriptions.some(x=>x.facility===id)||data.users.some(x=>x.facility===id)))||(k==='queues'&&data.bookings.some(x=>x.queue===id))||(k==='users'&&data.bookings.some(x=>x.user===id));modal(t('Delete record','حذف السجل'),'<p>'+esc(display(k,r))+'</p><p>'+ (deps?t('Reassign or remove linked records before deleting this record.','انقلي السجلات المرتبطة أو احذفيها قبل حذف هذا السجل.'):t('Delete this record from the workspace?','هل تريدين حذف هذا السجل من مساحة العمل؟'))+'</p>'+(!deps?'<button id="confirm" class="primary">'+t('Delete record','حذف السجل')+'</button>':''));if(!deps)$('confirm').onclick=()=>{write(k,null,id);log(k,'Deleted',display(k,r));$('dlg').close();render()}}
function profile(){if(live)return liveProfile();return head(L('settings'),t('Manage your platform administrator profile.','إدارة ملف مسؤول المنصة.'))+'<div class="panel section" style="max-width:560px"><form onsubmit="event.preventDefault();cache.profile=Object.fromEntries(new FormData(this));log(\'settings\',\'Updated\',cache.profile.name);render();modal(L(\'settings\'),\'<p>\'+t(\'Profile saved.\',\'تم حفظ الملف.\')+\'</p>\')">'+field('name',t('Display name','الاسم الظاهر'),cache.profile.name)+field('email',t('Email','البريد الإلكتروني'),cache.profile.email,'email')+'<p>'+t('Super Admin · Full platform access','الأدمن العام · صلاحية كاملة على المنصة')+'</p><button class="primary">'+t('Save profile','حفظ الملف')+'</button></form></div>'}
function audit(){return head(L('audit'),t('Administrative changes and operational events.','التغييرات الإدارية وأحداث النظام.'))+'<div class="panel section">'+events(true)+'</div>'}
function globalSearch(){modal(t('Search workspace','بحث في النظام'),'<input style="width:100%;margin:16px 0" id="gq" placeholder="'+t('Search names, IDs or sections…','ابحث بالاسم أو الرقم أو القسم…')+'"><div id="hits"></div>');let inp=$('gq');function results(){let q=inp.value.trim().toLowerCase(),out=keys.filter(k=>(L(k)+' '+k).toLowerCase().includes(q)).map(k=>'<button class="result" onclick="dlg.close();go(\''+k+'\')">'+L(k)+'</button>');if(q)for(const k of mKeys.concat(['notifications'])){let matches=0;for(const r of rows(k)){if([r.raw?.key,r.id,r.name,r.arabic,r.email].join(' ').toLowerCase().includes(q)){out.push('<button class="result" onclick="dlg.close();go(\''+k+'\');edit(\''+k+'\','+r.id+')">'+esc(display(k,r))+' · '+L(k)+' #'+r.id+'</button>');if(++matches===3)break}}}$('hits').innerHTML=out.join('')||'<p>'+t('No results','لا نتائج')+'</p>'}inp.oninput=results;results();inp.focus()}
render();

if(live)document.body.classList.add("live");

function recordActions(k,r) {
  const readOnly = live && ['bookings','queues'].includes(k);
  const editLabel = readOnly ? t('View','عرض') : t('Edit','تعديل');
  const canDelete = !live || ['categories','subscriptions','notifications'].includes(k);
  const action = (label,fn) => '<button class="outline" onclick="'+fn+'">'+label+'</button>';
  const call = (fn) => fn+"('"+k+"',"+r.id+")";
  return '<span style="display:inline-flex;gap:6px">'+action(editLabel,call('edit'))+
    (canDelete?action(t('Delete','حذف'),call('removeRow')):'')+'</span>';
}
